bool Codec<SCAddress>::encode(const SCAddress& v, Encoder& e) {
  switch (v.t_) {
    case SCAddressType::SC_ADDRESS_TYPE_ACCOUNT:
      if (const auto* p = std::get_if<0>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "SCAddress: payload does not match discriminant");
    case SCAddressType::SC_ADDRESS_TYPE_CONTRACT:
      if (const auto* p = std::get_if<1>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "SCAddress: payload does not match discriminant");
    case SCAddressType::SC_ADDRESS_TYPE_MUXED_ACCOUNT:
      if (const auto* p = std::get_if<2>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "SCAddress: payload does not match discriminant");
    case SCAddressType::SC_ADDRESS_TYPE_CLAIMABLE_BALANCE:
      if (const auto* p = std::get_if<3>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "SCAddress: payload does not match discriminant");
    case SCAddressType::SC_ADDRESS_TYPE_LIQUIDITY_POOL:
      if (const auto* p = std::get_if<4>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "SCAddress: payload does not match discriminant");
    case SCAddressType::SC_ADDRESS_TYPE_MUXED_CONTRACT:
      if (const auto* p = std::get_if<5>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "SCAddress: payload does not match discriminant");
    default: return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "SCAddress: unknown discriminant");
  }
}

bool Codec<SCAddress>::decode(SCAddress& v, Decoder& d) {
  Decoder::DepthGuard g(d);
  if (!g) return false;
  std::int32_t tag;
  if (!d.i32(tag)) return false;
  switch (tag) {
    case 0:
      v.t_ = static_cast<SCAddressType>(tag);
      v.v_.template emplace<0>();
      return d.field("accountId", std::get<0>(v.v_));
    case 1:
      v.t_ = static_cast<SCAddressType>(tag);
      v.v_.template emplace<1>();
      return d.field("contractId", std::get<1>(v.v_));
    case 2:
      v.t_ = static_cast<SCAddressType>(tag);
      v.v_.template emplace<2>();
      return d.field("muxedAccount", std::get<2>(v.v_));
    case 3:
      v.t_ = static_cast<SCAddressType>(tag);
      v.v_.template emplace<3>();
      return d.field("claimableBalanceId", std::get<3>(v.v_));
    case 4:
      v.t_ = static_cast<SCAddressType>(tag);
      v.v_.template emplace<4>();
      return d.field("liquidityPoolId", std::get<4>(v.v_));
    case 5:
      v.t_ = static_cast<SCAddressType>(tag);
      v.v_.template emplace<5>();
      return d.field("muxedContract", std::get<5>(v.v_));
    default: return d.fail(stellar::v1::ErrorCode::kDecodeFailed, "SCAddress: unknown discriminant");
  }
}

bool Codec<SCAddress>::gen(SCAddress& v, XdrRng& r, std::uint32_t depth) {
  std::size_t i = depth >= 4 ? 1 : r.index(6);
  switch (i) {
    case 0: {
      v.t_ = SCAddressType::SC_ADDRESS_TYPE_ACCOUNT;
      auto& p = v.v_.template emplace<0>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
    case 1: {
      v.t_ = SCAddressType::SC_ADDRESS_TYPE_CONTRACT;
      auto& p = v.v_.template emplace<1>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
    case 2: {
      v.t_ = SCAddressType::SC_ADDRESS_TYPE_MUXED_ACCOUNT;
      auto& p = v.v_.template emplace<2>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
    case 3: {
      v.t_ = SCAddressType::SC_ADDRESS_TYPE_CLAIMABLE_BALANCE;
      auto& p = v.v_.template emplace<3>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
    case 4: {
      v.t_ = SCAddressType::SC_ADDRESS_TYPE_LIQUIDITY_POOL;
      auto& p = v.v_.template emplace<4>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
    case 5: {
      v.t_ = SCAddressType::SC_ADDRESS_TYPE_MUXED_CONTRACT;
      auto& p = v.v_.template emplace<5>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
  }
  return false;
}

