bool Codec<ContractExecutable>::encode(const ContractExecutable& v, Encoder& e) {
  switch (v.t_) {
    case ContractExecutableType::CONTRACT_EXECUTABLE_WASM:
      if (const auto* p = std::get_if<0>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "ContractExecutable: payload does not match discriminant");
    case ContractExecutableType::CONTRACT_EXECUTABLE_STELLAR_ASSET:
      return e.i32(static_cast<std::int32_t>(v.t_));
    case ContractExecutableType::CONTRACT_EXECUTABLE_EXTERNAL_REF:
      if (const auto* p = std::get_if<2>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "ContractExecutable: payload does not match discriminant");
    default: return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "ContractExecutable: unknown discriminant");
  }
}

bool Codec<ContractExecutable>::decode(ContractExecutable& v, Decoder& d) {
  Decoder::DepthGuard g(d);
  if (!g) return false;
  std::int32_t tag;
  if (!d.i32(tag)) return false;
  switch (tag) {
    case 0:
      v.t_ = static_cast<ContractExecutableType>(tag);
      v.v_.template emplace<0>();
      return d.field("wasm_hash", std::get<0>(v.v_));
    case 1:
      v.t_ = static_cast<ContractExecutableType>(tag);
      v.v_.template emplace<1>();
      return true;
    case 2:
      v.t_ = static_cast<ContractExecutableType>(tag);
      v.v_.template emplace<2>();
      return d.field("external_ref", std::get<2>(v.v_));
    default: return d.fail(stellar::v1::ErrorCode::kDecodeFailed, "ContractExecutable: unknown discriminant");
  }
}

bool Codec<ContractExecutable>::gen(ContractExecutable& v, XdrRng& r, std::uint32_t depth) {
  std::size_t i = depth >= 4 ? 0 : r.index(3);
  switch (i) {
    case 0: {
      v.t_ = ContractExecutableType::CONTRACT_EXECUTABLE_WASM;
      auto& p = v.v_.template emplace<0>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
    case 1: {
      v.t_ = ContractExecutableType::CONTRACT_EXECUTABLE_STELLAR_ASSET;
      v.v_.template emplace<1>();
      return true;
    }
    case 2: {
      v.t_ = ContractExecutableType::CONTRACT_EXECUTABLE_EXTERNAL_REF;
      auto& p = v.v_.template emplace<2>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
  }
  return false;
}

